export const PAGE_SIZES = {
  full:   { label: 'Full Width', fluid: true },
  a4:     { label: 'A4',     portrait: { w: 794,  h: 1123 }, landscape: { w: 1123, h: 794  } },
  a3:     { label: 'A3',     portrait: { w: 1123, h: 1587 }, landscape: { w: 1587, h: 1123 } },
  letter: { label: 'Letter', portrait: { w: 816,  h: 1056 }, landscape: { w: 1056, h: 816  } },
  legal:  { label: 'Legal',  portrait: { w: 816,  h: 1344 }, landscape: { w: 1344, h: 816  } },
};

export function getPageDimensions(pageSize = 'a4', orientation = 'portrait') {
  const size = PAGE_SIZES[pageSize] ?? PAGE_SIZES.a4;
  return size[orientation] ?? size.portrait;
}

/** Returns a CSS style object for the page container based on its layout settings. */
export function getPageLayoutStyle(pageSize = 'a4', orientation = 'portrait') {
  if (pageSize === 'full') return { width: '100%', margin: '0' };
  const { w, h } = getPageDimensions(pageSize, orientation);
  return { width: `${w}px`, minHeight: `${h}px`, margin: '0 auto' };
}
