<template>
  <component
    :is="clickable ? 'button' : 'div'"
    class="fu-client-state-card"
    :class="{ 'fu-client-state-card--clickable': clickable }"
    :type="clickable ? 'button' : undefined"
    @click="onClick"
  >
    <FuAvatar
      class="fu-client-state-card__avatar"
      :name="initial || name"
      :bg="avatarBg"
      :color="avatarColor"
      size="lg"
    />

    <div class="fu-client-state-card__body">
      <div class="fu-client-state-card__header">
        <span class="fu-client-state-card__name">{{ name }}</span>

        <FusionBadge
          v-for="source in sources"
          :key="source"
          class="fu-client-state-card__source"
          :text="source"
          size="sm"
          variant="subtle"
        />
      </div>

      <div v-if="signals && signals.length" class="fu-client-state-card__signals">
        <FusionBadge
          v-for="(signal, i) in signals"
          :key="i"
          :text="signal.text"
          size="sm"
          :themeClass="signal.theme || 'fu-badge--danger-subtle'"
        />
      </div>
    </div>

    <FusionBadge
      v-if="status"
      class="fu-client-state-card__status"
      :text="status.text"
      size="md"
      :themeClass="status.theme || 'fu-badge--danger-subtle'"
    />
  </component>
</template>

<script setup lang="ts">
import FusionBadge from "../badge/FusionBadge.vue";
import FuAvatar from "../avatar/FuAvatar.vue";

export interface ClientSignalBadge {
  /** e.g. "No reply · 14 days" */
  text: string;
  /** FusionBadge themeClass, e.g. "fu-badge--danger-subtle" | "fu-badge--warning-subtle". Defaults to danger-subtle. */
  theme?: string;
}

export interface ClientStatusBadge {
  /** e.g. "At risk", "Needs attention", "Active" */
  text: string;
  /** FusionBadge themeClass. Defaults to danger-subtle. */
  theme?: string;
}

export interface FusionClientStateCardProps {
  /** Client/company name — also the source for the auto-derived initials when no `initial` is given */
  name: string;
  /** Overrides the auto-derived (first letter of each word) initials shown in the avatar */
  initial?: string;
  /** Avatar circle background color */
  avatarBg?: string;
  /** Avatar initials text color */
  avatarColor?: string;
  /** Connected signal sources this client is read from, e.g. ["CRM", "Stripe", "Gmail"] */
  sources?: string[];
  /** Specific attention signals read from those sources, e.g. "Invoice overdue · 7 days" */
  signals?: ClientSignalBadge[];
  /** Overall attention state shown on the right, e.g. "At risk" */
  status?: ClientStatusBadge;
  /** Renders as a `<button>` with hover/focus affordance and emits `click` */
  clickable?: boolean;
}

const props = withDefaults(defineProps<FusionClientStateCardProps>(), {
  avatarBg: "#fee2e2",
  avatarColor: "#991b1b",
  sources: () => [],
  signals: () => [],
  clickable: true,
});

const emit = defineEmits<{ (e: "click"): void }>();

function onClick() {
  if (props.clickable) emit("click");
}
</script>

