<template>
  <div class="document-root">
    <PageRenderer
      v-for="page in document.pages"
      :key="page.id"
      :page="page"
      :theme="document.meta?.theme"
      @action="$emit('action', $event)"
    />
  </div>
</template>

<script setup lang="ts">
import { watchEffect } from "vue";
import PageRenderer from "../pageRender/PageRenderer.vue";
import { preloadDocumentFonts } from "../../../utils/preloadDocumentFonts";

const props = defineProps<{
  document: any;
}>();

defineEmits(["action"]);

watchEffect(() => preloadDocumentFonts(props.document));
</script>
